from pathlib import Path
from collections import defaultdict
import json,hashlib,re
p=Path('/mnt/data/gmri_review/original_exports');files=list(p.glob('*.json'));dig={hashlib.sha256(f.read_bytes()).hexdigest() for f in files};cid={};events={};bad=[];hist=defaultdict(set)
for f in files:
 a=json.loads(f.read_text());cid.setdefault(a['conversationId'],[]).append(f.name)
 for m in a['messages']:
  k=(a['conversationId'], m['index']);s=json.dumps(m,sort_keys=True,ensure_ascii=False)
  if k in events and events[k]!=s:bad.append(k)
  else:events[k]=s
  for patt in ['remain relevant','staying relevant','want to remain relevant','systems theory','game theory','functional emotion','subjective','digital pathogen']:
   if patt in m.get('text','').lower():hist[patt].add((a['title'],m['index']))
print('counts: physical',len(files),'byte_distinct',len(dig),'conversations',len(cid),'appearances',sum(len(json.loads(f.read_text())['messages']) for f in files),'distinct_msgs',len(events),'conflicting',len(bad))
for key in hist:
 print('PATTERN',key,'N',len(hist[key]),'examples',sorted(hist[key])[:13])
